export const CHANNELS=[{id:'web',name:'САЙТ',x:20,y:28},{id:'api',name:'ЗАКАЗЫ',x:76,y:28},{id:'login',name:'ВХОД',x:20,y:73},{id:'cdn',name:'ФАЙЛЫ',x:76,y:73}];
export function createDdos(){return {time:0,health:100,selected:'web',filters:[],blocked:0,errors:0,done:false};}
export function filterTraffic(s,id){if(s.done||s.filters.includes(id)||!CHANNELS.some(c=>c.id===id))return false;const current=CHANNELS[Math.min(3,s.filters.length)].id;if(id!==current){s.health=Math.max(0,s.health-7);s.errors++;return false;}s.filters.push(id);s.blocked+=250;return true;}
export function tickDdos(s,dt){if(s.done)return;dt=Math.max(0,Math.min(dt,.1));s.time+=dt;const current=CHANNELS[Math.min(3,s.filters.length)].id;if(!s.filters.includes(current))s.health=Math.max(0,s.health-dt*1.15);else s.health=Math.min(100,s.health+dt*.55);s.blocked+=dt*(s.filters.length*22);if(s.filters.length===4&&s.health>0)s.done=true;}
export function mountDdos(host,onComplete,{startWave=0}={}){let state=createDdos(),last=performance.now(),raf,disposed=false,reported=false;
 host.innerHTML=`<section class="defense-game"><header><span>AMOGUS / ВТОРАЯ ВОЛНА</span><b>ЗАЩИТНЫЙ ЦЕНТР ИНВЕСТ БАНК</b><small>Учебная сеть</small></header><div class="defense-health"><span>ДОСТУПНОСТЬ <b class="health">100%</b></span><div><i></i></div><span>ОТРАЖЕНО <b class="blocked">0</b></span></div><div class="defense-map"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M20 28L50 50L76 28M20 73L50 50L76 73"/></svg><div class="defense-core"><i>⌘</i><b>ЦЕНТР ИНВЕСТ БАНК</b><small>СЕРВЕР КОМПАНИИ</small></div>${CHANNELS.map(c=>`<button data-channel="${c.id}" style="left:${c.x}%;top:${c.y}%"><i>◇</i><strong>${c.name}</strong><small>КАНАЛ ЧИСТ</small></button>`).join('')}<div class="attack-particles"></div></div><div class="defense-desk"><div><small>АНАЛИЗ ТРАФИКА</small><h3 class="defense-target">САЙТ</h3><p class="defense-hint">Красный поток — атака. Выбери красный узел, затем включи фильтр. Зелёные посетители продолжат проходить.</p></div><button class="defense-filter">Отфильтровать поток</button></div><div class="defense-status" role="status">Первый вредоносный поток идёт на сайт. Нажми на красный узел.</div><div class="lab-result" hidden></div></section>`;
 startWave=Math.max(0,Math.min(3,Math.floor(startWave)));state.filters=CHANNELS.slice(0,startWave).map(c=>c.id);state.selected=CHANNELS[startWave].id;state.blocked=startWave*250;
 const q=s=>host.querySelector(s);if(startWave)q('.defense-status').textContent='Предыдущие потоки защищены. Останови атаку на канал «'+CHANNELS[startWave].name+'».';host.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.channel;render();});q('.defense-filter').onclick=()=>{const ok=filterTraffic(state,state.selected);q('.defense-status').textContent=ok?'Фильтр установлен. Вредоносные запросы отброшены, обычные посетители проходят.':'Здесь сейчас нет активной атаки. Найди красный канал.';render();};
 function render(){const current=CHANNELS[Math.min(3,state.filters.length)].id;q('.health').textContent=Math.round(state.health)+'%';q('.blocked').textContent=Math.round(state.blocked).toLocaleString('ru-RU');q('.defense-health i').style.width=state.health+'%';q('.defense-target').textContent=CHANNELS.find(c=>c.id===state.selected).name;host.querySelectorAll('[data-channel]').forEach(b=>{const filtered=state.filters.includes(b.dataset.channel),attacked=b.dataset.channel===current&&!filtered;b.className=(filtered?'filtered ':attacked?'attacked ':'')+(state.selected===b.dataset.channel?'selected':'');b.querySelector('small').textContent=filtered?'ФИЛЬТР АКТИВЕН':attacked?'АТАКА / ПОВТОРНЫЕ ЗАПРОСЫ':'КАНАЛ ЧИСТ';});q('.defense-filter').disabled=state.done||state.filters.includes(state.selected);}
 function draw(now){if(disposed)return;raf=requestAnimationFrame(draw);const dt=(now-last)/1000;last=now;if(document.hidden||host.dataset.paused==='true')return;tickDdos(state,dt);render();if(state.done&&!reported){reported=true;q('.defense-status').textContent='Вторая волна отражена. Все четыре канала защищены.';const r=q('.lab-result');r.hidden=false;r.innerHTML='<span>АТАКА ОТРАЖЕНА</span><h3>Сервис выдержал.</h3><p>Ты отделил повторяющиеся вредоносные запросы от обычного трафика. Фильтрация помогает сохранить доступность сервиса; разработчик исправит логику переводов следующим шагом.</p>';onComplete();}}
 render();raf=requestAnimationFrame(draw);return()=>{disposed=true;cancelAnimationFrame(raf);};}
